package pe.edu.vallegrande.crud.model;
import jakarta.persistence.*; import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.LocalDate; import java.time.LocalDateTime;
@Entity @Table(name="assessment")
public class Assessment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="assessment_id") private Integer id; @NotNull @Column(name="section_course_id",nullable=false) private Integer sectionCourseId; @NotNull @Column(name="competency_id",nullable=false) private Integer competencyId; @NotBlank @Size(max=150) @Column(name="assessment_name",nullable=false,length=150) private String assessmentName; @NotNull @Column(name="assessment_date",nullable=false) private LocalDate assessmentDate; @NotNull @DecimalMin("0.01") @Column(name="maximum_score",nullable=false,precision=5,scale=2) private BigDecimal maximumScore; @Column(nullable=false,length=15) private String status="PROGRAMADA"; @Column(name="created_at",insertable=false,updatable=false) private LocalDateTime createdAt; public Integer getId(){return id;} public void setId(Integer v){id=v;} public Integer getSectionCourseId(){return sectionCourseId;} public void setSectionCourseId(Integer v){sectionCourseId=v;} public Integer getCompetencyId(){return competencyId;} public void setCompetencyId(Integer v){competencyId=v;} public String getAssessmentName(){return assessmentName;} public void setAssessmentName(String v){assessmentName=v;} public LocalDate getAssessmentDate(){return assessmentDate;} public void setAssessmentDate(LocalDate v){assessmentDate=v;} public BigDecimal getMaximumScore(){return maximumScore;} public void setMaximumScore(BigDecimal v){maximumScore=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public LocalDateTime getCreatedAt(){return createdAt;} }
